import{_ as a,o as i,c as t,a4 as n}from"./chunks/framework.BMj-uaUw.js";const k=JSON.parse('{"title":"AI 编程工具速查","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、工具速查表","slug":"一、工具速查表","link":"#一、工具速查表","children":[{"level":3,"title":"国内工具","slug":"国内工具","link":"#国内工具","children":[]},{"level":3,"title":"海外工具（只作对照）","slug":"海外工具-只作对照","link":"#海外工具-只作对照","children":[]}]},{"level":2,"title":"二、选工具的三步","slug":"二、选工具的三步","link":"#二、选工具的三步","children":[]},{"level":2,"title":"三、AGENTS.md 模板","slug":"三、agents-md-模板","link":"#三、agents-md-模板","children":[{"level":3,"title":"最小可用版","slug":"最小可用版","link":"#最小可用版","children":[]},{"level":3,"title":"几个写作要点","slug":"几个写作要点","link":"#几个写作要点","children":[]}]},{"level":2,"title":"四、提示词句式库","slug":"四、提示词句式库","link":"#四、提示词句式库","children":[{"level":3,"title":"4.1 解释类","slug":"_4-1-解释类","link":"#_4-1-解释类","children":[]},{"level":3,"title":"4.2 生成类","slug":"_4-2-生成类","link":"#_4-2-生成类","children":[]},{"level":3,"title":"4.3 排查类","slug":"_4-3-排查类","link":"#_4-3-排查类","children":[]},{"level":3,"title":"4.4 审查类","slug":"_4-4-审查类","link":"#_4-4-审查类","children":[]},{"level":3,"title":"4.5 让它承认不确定","slug":"_4-5-让它承认不确定","link":"#_4-5-让它承认不确定","children":[]}]},{"level":2,"title":"五、AI 代码审查清单","slug":"五、ai-代码审查清单","link":"#五、ai-代码审查清单","children":[{"level":3,"title":"5.1 通用清单","slug":"_5-1-通用清单","link":"#_5-1-通用清单","children":[]},{"level":3,"title":"5.2 AI 代码的六种典型问题","slug":"_5-2-ai-代码的六种典型问题","link":"#_5-2-ai-代码的六种典型问题","children":[]}]},{"level":2,"title":"六、核实命令","slug":"六、核实命令","link":"#六、核实命令","children":[]},{"level":2,"title":"七、AI 相关术语","slug":"七、ai-相关术语","link":"#七、ai-相关术语","children":[]},{"level":2,"title":"怎么用这一页","slug":"怎么用这一页","link":"#怎么用这一页","children":[]}],"relativePath":"appendix/ai-tools.md","filePath":"appendix/ai-tools.md","lastUpdated":1789356885000}'),e={name:"appendix/ai-tools.md"};function l(p,s,d,h,r,o){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="ai-编程工具速查" tabindex="-1">AI 编程工具速查 <a class="header-anchor" href="#ai-编程工具速查" aria-label="Permalink to &quot;AI 编程工具速查&quot;">​</a></h1><p>这一页是 AI 协作的<strong>工具区</strong>。正文讲方法与边界，这里按“你此刻要解决的问题”来查。</p><ul><li>不知道选哪个工具 → 看<a href="#一工具速查表">第一节的工具速查表</a>。</li><li>要让 AI 先读懂你的项目 → 抄<a href="#三agentsmd-模板">第三节的 AGENTS.md 模板</a>。</li><li>知道要什么但说不清 → 翻<a href="#四提示词句式库">第四节的提示词句式库</a>。</li><li>拿到 AI 的代码不知道从哪审起 → 用<a href="#五ai-代码审查清单">第五节的审查清单</a>。</li><li>想确认 AI 说的包和版本是真的 → 跑<a href="#六核实命令">第六节的核实命令</a>。</li></ul><h2 id="一、工具速查表" tabindex="-1">一、工具速查表 <a class="header-anchor" href="#一、工具速查表" aria-label="Permalink to &quot;一、工具速查表&quot;">​</a></h2><p>先给结论：<strong>学生阶段按“能直接用、不花钱、中文好”三条选，不要比参数。</strong> 一年内工具排名就换过一轮，比较工具型号的收益很低，练描述能力与审查能力的收益很高。</p><h3 id="国内工具" tabindex="-1">国内工具 <a class="header-anchor" href="#国内工具" aria-label="Permalink to &quot;国内工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>形态</th><th>费用</th><th>适合的场景</th><th>注意点</th></tr></thead><tbody><tr><td>字节 Trae</td><td>独立 IDE（基于 VS Code 架构）</td><td>基础版免费</td><td><strong>零基础起步</strong>。插件与快捷键和 VS Code 通用，Agent 模式开箱可用，中文理解好</td><td>对超大存量仓库的全局重构能力弱一些</td></tr><tr><td>腾讯 CodeBuddy</td><td>IDE 插件、独立 IDE、命令行三种形态</td><td>有免费额度</td><td>想练<strong>规范驱动流程</strong>。它主推 SPEC 模式，流程是需求澄清 → 任务拆解 → 代码预审 → 安全拦截</td><td>流程约束强，前期会觉得啰嗦</td></tr><tr><td>阿里 Qoder CN</td><td>独立 IDE</td><td>有免费额度，重度任务消耗快</td><td>项目变大后需要工具<strong>记住整个仓库结构</strong>时用，支持仓库知识库与长上下文</td><td>由通义灵码更名而来，老教程里的名字可能还是旧的</td></tr><tr><td>百度文心快码</td><td>插件与 IDE</td><td>个人版免费</td><td>已经在用百度系产品时顺带使用</td><td>—</td></tr></tbody></table><p>2026 年 5 月国内 AI 编程 IDE 的市场份额大致是 CodeBuddy 28%、Qoder CN 26%、Trae 24%、文心快码 22%，四家差距不大，<strong>没有一家能通吃所有场景</strong>。</p><h3 id="海外工具-只作对照" tabindex="-1">海外工具（只作对照） <a class="header-anchor" href="#海外工具-只作对照" aria-label="Permalink to &quot;海外工具（只作对照）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>工作场景使用率</th><th>定位</th></tr></thead><tbody><tr><td>Claude Code</td><td>39%（2026 年 1 月为 18%）</td><td>使用率第一，命令行代理形态，美国使用率达 47%</td></tr><tr><td>GitHub Copilot</td><td>21%（去年同期 29%）</td><td>最早的 AI 补全工具，认知度仍最高</td></tr><tr><td>OpenAI Codex</td><td>16%（2026 年 1 月为 3%）</td><td>半年增长约 5 倍</td></tr><tr><td>Cursor</td><td>12%（2026 年 1 月为 18%）</td><td>编辑器形态的代理，中国区使用率从 28% 降到 16%</td></tr></tbody></table><p>这些工具在中国大陆没有官方的合规服务，存在网络不稳、账号被封、数据出境这几类风险。<strong>做课程项目优先用本土工具</strong>，不要在这件事上耗时间。</p><div class="warning custom-block"><p class="custom-block-title">别做的事</p><p>不要为了用某个工具去借账号、买代充、装来路不明的东西。<strong>课程考核的是能力，不是工具型号。</strong></p></div><h2 id="二、选工具的三步" tabindex="-1">二、选工具的三步 <a class="header-anchor" href="#二、选工具的三步" aria-label="Permalink to &quot;二、选工具的三步&quot;">​</a></h2><ol><li><strong>装上能免费用的那一个，用两周。</strong> 不用比较，先有手感。</li><li><strong>两周后如果觉得“它老听不懂我要什么”，先别换工具。</strong> 问题通常在描述方式上，去翻<a href="#四提示词句式库">第四节的句式库</a>。</li><li><strong>等你能稳定把一次任务描述清楚，再考虑换。</strong> 工具换起来很快，描述能力换不掉。</li></ol><h2 id="三、agents-md-模板" tabindex="-1">三、AGENTS.md 模板 <a class="header-anchor" href="#三、agents-md-模板" aria-label="Permalink to &quot;三、AGENTS.md 模板&quot;">​</a></h2><h3 id="最小可用版" tabindex="-1">最小可用版 <a class="header-anchor" href="#最小可用版" aria-label="Permalink to &quot;最小可用版&quot;">​</a></h3><p>放在仓库根目录，与代码一起提交。先从这个版本开始，遇到新问题就往上加：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 项目约定</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 常用命令</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 装依赖：pnpm install</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 开发：pnpm dev</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 构建：pnpm build</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 检查：pnpm lint</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">改完先跑 lint 再提交。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 技术栈</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Vue 3.5（组合式 API + script setup）+ Vite 8 + Vue Router 5 + Pinia 4 +</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Element Plus 2，包管理用 pnpm。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 目录约定</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src/views      页面组件，一个路由一个文件</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src/components 通用组件，被两处以上复用才放进来</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src/api        接口函数，按业务模块分文件</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src/stores     Pinia store，一个模块一个文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 接口约定</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 响应格式 { code, message, data }，成功码是 0，不是 200</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 前端字段用驼峰，后端返回下划线，转换在 api 层做</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 禁止事项</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要写任何密钥、token、真实账号密码</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要删除你没有确认过引用位置的代码</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要引入新的 UI 库或状态管理库</span></span></code></pre></div><h3 id="几个写作要点" tabindex="-1">几个写作要点 <a class="header-anchor" href="#几个写作要点" aria-label="Permalink to &quot;几个写作要点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要点</th><th>说明</th></tr></thead><tbody><tr><td>命令放最前面</td><td>AI 最常见的错误之一是编造命令，写在最前面能明显减少</td></tr><tr><td>禁止事项要具体</td><td>“不写密钥”“不删未确认引用的代码”这类边界说明，比冗长的风格清单更有效</td></tr><tr><td>控制在一两百行</td><td>只做导航性说明，细节用链接指向别的文档。这个做法叫“渐进式披露”</td></tr><tr><td>每条都要能对上项目</td><td>写“成功码是 0”之前确认你们的后端真是这样，写错了比不写更糟</td></tr><tr><td>支持分层</td><td>子目录可以再放一份更细的，AI 处理该目录文件时就近的覆盖上层的</td></tr></tbody></table><p>完整的项目级模板（含业务规则、提交规范、代码风格）见<a href="/frontend-engineering-course/project/ai-collaboration.html#一仓库根目录的-agentsmd">综合项目的 AI 协作规范</a>。</p><h2 id="四、提示词句式库" tabindex="-1">四、提示词句式库 <a class="header-anchor" href="#四、提示词句式库" aria-label="Permalink to &quot;四、提示词句式库&quot;">​</a></h2><p>提示词的效果差异，八成来自三件事：<strong>给了多少上下文、约束写没写清、要什么格式的输出。</strong></p><p>下面按用途分组，方括号里是要你自己填的部分。</p><h3 id="_4-1-解释类" tabindex="-1">4.1 解释类 <a class="header-anchor" href="#_4-1-解释类" aria-label="Permalink to &quot;4.1 解释类&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用一句话解释 [概念] 是什么、解决什么问题、什么时候不该用它。</span></span>
<span class="line"><span>不要展开，不要举例，我要的是判断标准。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这段代码是做什么的？请按三部分回答：</span></span>
<span class="line"><span>1. 输入是什么、输出是什么</span></span>
<span class="line"><span>2. 关键的那一两个设计决定，以及为什么这么做</span></span>
<span class="line"><span>3. 如果这里出错，会表现出什么现象</span></span></code></pre></div><p><strong>为什么这么写</strong>：加上“按三部分回答”，输出的结构就固定了，你不用在散乱的文字里找重点。最后一句问“出错会怎么表现”，其实是在帮你准备验收动作。</p><h3 id="_4-2-生成类" tabindex="-1">4.2 生成类 <a class="header-anchor" href="#_4-2-生成类" aria-label="Permalink to &quot;4.2 生成类&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先读仓库根目录的 AGENTS.md 和 [文档路径]，按照 [任务文档路径] 的要求实现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 只创建 [文件列表]，不要修改其他已有文件</span></span>
<span class="line"><span>2. 接口只用 [接口清单路径] 里列出的，不要新增接口</span></span>
<span class="line"><span>3. [项目特定约束，例如：成功码是 0]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先不要写代码，先把实现计划讲一遍，包含你打算改哪些文件、</span></span>
<span class="line"><span>每个文件做什么、有哪些地方你不确定。我确认后你再写。</span></span></code></pre></div><p><strong>为什么这么写</strong>：四个约束分别防四类问题 —— 改超范围、编造接口、违反项目约定、想错方向。“先讲计划”这一条最省时间：看错计划只要一分钟就能纠正，代码写错了要重来。</p><h3 id="_4-3-排查类" tabindex="-1">4.3 排查类 <a class="header-anchor" href="#_4-3-排查类" aria-label="Permalink to &quot;4.3 排查类&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报错原文：</span></span>
<span class="line"><span>[完整粘贴，不要删减]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我的操作：[做了什么触发的]</span></span>
<span class="line"><span>已经试过：[试过什么，结果如何]</span></span>
<span class="line"><span>相关文件：[涉及的文件路径]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请回答：</span></span>
<span class="line"><span>1. 这个报错最可能的原因是什么，按可能性排序，给出判断依据</span></span>
<span class="line"><span>2. 为了确认是哪一种，我下一步应该看什么、跑什么命令</span></span>
<span class="line"><span>3. 每种原因对应的改法</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不确定的地方直接说不确定，不要给猜测性的结论。</span></span></code></pre></div><p><strong>为什么这么写</strong>：“已经试过”这一段能省掉大量来回。最后一句很关键 —— 不写这句，AI 倾向于给一个听起来确定的答案，而不是说“我不确定”。</p><h3 id="_4-4-审查类" tabindex="-1">4.4 审查类 <a class="header-anchor" href="#_4-4-审查类" aria-label="Permalink to &quot;4.4 审查类&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请审查 [文件路径] 的这段改动，重点看：</span></span>
<span class="line"><span>1. 有没有违反 AGENTS.md 里的约定</span></span>
<span class="line"><span>2. 加载中、空数据、出错三种状态处理了吗</span></span>
<span class="line"><span>3. 有没有硬编码的假数据、密钥、调试用的输出</span></span>
<span class="line"><span>4. 有没有改动这段代码不该改的地方</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每条问题请给出：文件与位置、为什么是问题、怎么改。</span></span>
<span class="line"><span>没有问题就说没有问题，不要为了凑数硬找。</span></span></code></pre></div><p><strong>为什么这么写</strong>：最后一句必要。不写这句，它经常为了让输出“看起来有价值”而挑一些不重要的小毛病，你会被淹没在无关建议里。</p><h3 id="_4-5-让它承认不确定" tabindex="-1">4.5 让它承认不确定 <a class="header-anchor" href="#_4-5-让它承认不确定" aria-label="Permalink to &quot;4.5 让它承认不确定&quot;">​</a></h3><p>这三句可以随时追加，很实用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这条结论你有把握吗？如果没有，直接说没有把握，不要猜。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个包名和版本号，你确定在官方仓库里存在吗？如果不确定，告诉我怎么核实。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你刚才建议我删除这个文件，请先给出检索它是否被引用的命令，我自己跑一遍。</span></span></code></pre></div><h2 id="五、ai-代码审查清单" tabindex="-1">五、AI 代码审查清单 <a class="header-anchor" href="#五、ai-代码审查清单" aria-label="Permalink to &quot;五、AI 代码审查清单&quot;">​</a></h2><h3 id="_5-1-通用清单" tabindex="-1">5.1 通用清单 <a class="header-anchor" href="#_5-1-通用清单" aria-label="Permalink to &quot;5.1 通用清单&quot;">​</a></h3><p>按类别过，比从头读一遍快，也不容易漏。</p><p><strong>接口与数据</strong></p><ul><li>[ ] 成功码用的是 <code>0</code>，不是 <code>200</code></li><li>[ ] 错误分支有处理，错误码被挂到了 Error 对象上（<code>err.code = code</code>）</li><li>[ ] 页面里没有出现后端下划线字段，转换在 api 层做了</li><li>[ ] 用到的接口都在接口清单里，没有编造的接口</li><li>[ ] 没有硬编码的假数据残留</li></ul><p><strong>状态与渲染</strong></p><ul><li>[ ] 加载中、空数据、出错三种状态都有对应界面</li><li>[ ] <code>v-for</code> 用了稳定的业务 id 作 <code>key</code>，不是数组下标</li><li>[ ] 没有把能算出来的值另存一份状态</li><li>[ ] 解构响应式对象时没有切断响应式</li><li>[ ] 没有在子组件里修改 props 或 props 对象的内部属性</li></ul><p><strong>边界与异常</strong></p><ul><li>[ ] 空数组、空字符串、<code>null</code> 时页面不报错</li><li>[ ] 数字为 0、字符串为空时判断逻辑仍然正确</li><li>[ ] 提交类按钮有防重复点击</li><li>[ ] 组件卸载时清理了定时器、事件监听、<code>watch</code></li></ul><p><strong>安全</strong></p><ul><li>[ ] 没有密钥、token、真实账号密码</li><li>[ ] 没有用前端判断当权限控制的唯一手段</li><li>[ ] 没有把不可信内容直接当 HTML 渲染</li><li>[ ] 没有 token 出现在日志或地址栏里</li></ul><p><strong>可维护</strong></p><ul><li>[ ] 没有 <code>console.log</code> 残留</li><li>[ ] 命名与项目其他部分一致</li><li>[ ] 没有重复实现项目里已有的工具函数或组件</li><li>[ ] 改动范围与预期一致（<code>git diff --name-only</code> 看一眼）</li></ul><h3 id="_5-2-ai-代码的六种典型问题" tabindex="-1">5.2 AI 代码的六种典型问题 <a class="header-anchor" href="#_5-2-ai-代码的六种典型问题" aria-label="Permalink to &quot;5.2 AI 代码的六种典型问题&quot;">​</a></h3><p>这类问题的共同点是：<strong>看起来对，但不一定对。</strong> 人工代码的典型错误是命名不规范、边界漏判、逻辑写反；AI 的典型错误不是“明显写错”，是“补全了你没说清的地方”。有统计显示 AI 生成代码平均每个 PR 的问题数是人工代码的 1.7 倍，其中九成以上属于不立即报错但长期难维护的问题。</p><p>下面六种按出现频率排，每种给出识别方法。</p><p><strong>一、编造的依赖</strong></p><p>现象：<code>package.json</code> 里出现一个命名完全符合规范、版本号也合理的包，但仓库里没有。</p><p>识别：装之前先在浏览器打开 <code>https://www.npmjs.com/package/[包名]</code> 确认存在。或跑：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/[包名]/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span></code></pre></div><p>如果返回 <code>{&quot;error&quot;:&quot;Not found&quot;}</code>，这个包不存在。</p><p><strong>二、默认约定写错</strong></p><p>现象：按行业最常见的方式写，而不是按你们项目的约定写。典型是成功码写成 <code>200</code>，而项目约定是 <code>0</code>。</p><p>识别：把 AGENTS.md 里的约定逐条对照生成的代码。这类问题单靠读代码看不出来，因为两种写法看起来一样合理。</p><p><strong>三、把错误信息丢掉</strong></p><p>现象：拦截器里写 <code>Promise.reject(new Error(message))</code>，业务码 <code>code</code> 丢失，页面里 <code>e.code === 2005</code> 永远不成立。</p><p>识别：搜一遍项目里所有判断业务码的地方，看它们依赖的字段是不是真的传到了。</p><p><strong>四、只写成功路径</strong></p><p>现象：函数只有正常返回的分支，没有失败处理；页面只有“有数据”这一种显示。</p><p>识别：对着每个请求问一句“如果这个请求失败了，页面会显示什么”。答不出来就是漏了。</p><p><strong>五、状态放错位置</strong></p><p>现象：组合式函数把状态定义在模块作用域（写在 <code>export function</code> 外面），所有用到它的组件共享同一份数据。两个列表页互相影响，且只在同时打开时才复现。</p><p>识别：看组合式函数里 <code>ref</code> / <code>reactive</code> 定义在函数体内还是函数体外。定义在体外就是在共享。</p><p><strong>六、建议删除“看起来没人用”的代码</strong></p><p>现象：AI 判断某个文件或函数没有被引用，建议删掉。但这个文件可能是路由懒加载或动态导入进来的。</p><p>识别：<strong>任何删除建议都先让它给出检索命令，自己跑一遍确认。</strong> 例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;组件名&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.vue&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.js&quot;</span></span></code></pre></div><p>搜不到不等于没人用 —— 动态导入的路径往往是以变量拼出来的。</p><h2 id="六、核实命令" tabindex="-1">六、核实命令 <a class="header-anchor" href="#六、核实命令" aria-label="Permalink to &quot;六、核实命令&quot;">​</a></h2><p>AI 给的版本号和包名一律要核。三个常用命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查包的最新版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/vue/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 包名里带斜杠的，斜杠要转义成 %2F</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/@vue%2Fuse%2Fcore/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查某个命令行工具是否存在</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span></span></code></pre></div><p>Node 各版本的 LTS 名称与发布时间：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://nodejs.org/dist/index.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">为什么必须自己核</p><p>AI 的训练数据有截止时间，它给出的版本号<strong>一定</strong>会过期，而且它有时会把版本号和包名“拼”出来。这类错误的识别成本很高，因为它看起来完全合理。</p></div><h2 id="七、ai-相关术语" tabindex="-1">七、AI 相关术语 <a class="header-anchor" href="#七、ai-相关术语" aria-label="Permalink to &quot;七、AI 相关术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th><th>常见误解</th></tr></thead><tbody><tr><td>编码代理 Coding Agent</td><td>能读文件、改文件、跑命令的 AI 工具，不只是补全</td><td>以为它和补全是同一类东西。补全帮你打字，代理替你把事做完</td></tr><tr><td>上下文工程 Context Engineering</td><td>决定往对话里放哪些信息，让产出更准</td><td>以为提示词越长越好。无关信息会稀释重点</td></tr><tr><td>AGENTS.md</td><td>放在仓库根目录、告诉 AI 项目约定的 Markdown 文件</td><td>以为它是某个工具的专有配置。它是跨工具的通用格式</td></tr><tr><td>渐进式披露 Progressive Disclosure</td><td>主文件只放导航性信息，细节按需展开</td><td>以为把所有内容塞进一个文件更好</td></tr><tr><td>MCP</td><td>让 AI 连接外部服务（数据库、接口、内部系统）的一套协议</td><td>以为要自己实现。知道它是什么、什么时候需要就够</td></tr><tr><td>Agent Skills</td><td>把一套流程和资料打包成可复用的能力，AI 按需加载</td><td>以为要写代码。它就是一个目录加一份 Markdown</td></tr><tr><td>规格驱动开发 SDD</td><td>先写清“要建什么、为什么”，再让 AI 按规格实现</td><td>以为要多写一堆文档。规格就是需求、规则、接口这几份</td></tr><tr><td>提示注入 Prompt Injection</td><td>把恶意指令藏在 AI 会读到的地方，让它执行不该执行的操作</td><td>以为只在安全领域才需要关心。2026 年 3 月已出现针对编码代理的真实攻击</td></tr><tr><td>验证缺口 Verification Gap</td><td>多数人知道 AI 代码不能全信，但不到一半的人每次提交前真的检查</td><td>以为“看着跑通了”就等于验证过</td></tr><tr><td>代码异味 Code Smell</td><td>不立即报错、但让代码越来越难维护的写法</td><td>以为只有报错的问题才算问题。有研究显示 AI 代码九成以上的问题属于这一类</td></tr><tr><td>幻觉依赖 Hallucinated Dependency</td><td>AI 编出来的、仓库里不存在的包名或坐标</td><td>以为名字符合规范就一定是真的</td></tr></tbody></table><p>更完整的通用术语见<a href="/frontend-engineering-course/appendix/glossary.html">术语表</a>。</p><h2 id="怎么用这一页" tabindex="-1">怎么用这一页 <a class="header-anchor" href="#怎么用这一页" aria-label="Permalink to &quot;怎么用这一页&quot;">​</a></h2><p>不要通读。它是遇到问题时来查的。</p><p>一个建议的用法是：<strong>每次让 AI 产出代码后，用<a href="#五ai-代码审查清单">第五节的清单</a>过一遍，把踩到的问题记在自己的开发记录里。</strong> 前两次会花十几分钟，三五次之后就变成条件反射了 —— 这时候你审 AI 代码的速度，会比手写快得多。</p><hr><p>上一节：<a href="/frontend-engineering-course/appendix/glossary.html">术语表</a> · 返回：<a href="/frontend-engineering-course/appendix/">附录总览</a></p>`,94)])])}const g=a(e,[["render",l]]);export{k as __pageData,g as default};
